  "scen.lancet": { de: "Lancet-Survey: 75.200 Gewalttote bis 5.1.25", en: "Lancet survey: 75,200 violent deaths by Jan 5, 25", ar: "مسح لانسيت: 75,200 قتيل عنف حتى 5.1.25", he: "סקר לנסט: 75,200 הרוגי אלימות עד 5.1.25" },
  "scen.adj": { de: "Szenario: {0}", en: "scenario: {0}", ar: "السيناريو: {0}", he: "תרחיש: {0}" },
